import AppKit
import Foundation

/// Recently copied text, for the "Recently copied" part of the prompt.
///
/// It watches the general pasteboard's change count (metadata only, which never reads the contents) to learn when
/// something was copied, and reads the text only when asked and only if the copy is recent. Items that password
/// managers and other apps mark as concealed, transient or auto-generated are skipped, as is anything that looks
/// like a credential.
///
/// Since macOS 15.4 reading another app's pasteboard contents can show a system alert ("Paste from Other Apps" in
/// macOS 27). By default this provider doesn't read when that would happen; see `Configuration.readWhenItWouldPrompt`
/// and `requestAccess()`.
public final class ClipboardContextProvider: @unchecked Sendable {
    public struct Configuration: Sendable {
        /// Longer text is cut to this many characters.
        public var maxCharacters = 4000
        public var redactSecrets = true
        /// Read even when the system would show its paste-permission alert. Off by default, since the alert would
        /// appear in the middle of typing, once per copy.
        public var readWhenItWouldPrompt = false
        /// How often the change count is sampled once monitoring starts.
        public var pollInterval: TimeInterval = 1
        /// Pasteboard types whose presence means "don't look": nspasteboard.org markers and 1Password's own type.
        public var skippedTypes: Set<String> = ClipboardContextProvider.defaultSkippedTypes

        public init() {}
    }

    public static let defaultSkippedTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
        "de.petermaurer.TransientPasteboardType",
    ]

    /// Whether reading the pasteboard's contents is possible without a system alert.
    public enum Access: Sendable, Equatable {
        /// Reading is silent.
        case allowed
        /// Reading shows the system alert (the user hasn't chosen "Always Allow" in System Settings).
        case prompts
        /// The user denied access in System Settings; reads return nothing.
        case denied
    }

    public let configuration: Configuration

    private let source: PasteboardSource
    private let now: () -> Date
    private let lock = NSLock()
    private var lastChangeCount: Int
    /// When the change count last moved, as observed. Nil until a change is seen after launch.
    private var changedAt: Date?
    /// Processed result for `lastChangeCount`, so each copy is read at most once.
    private var cached: (changeCount: Int, text: String?)?
    private var timer: DispatchSourceTimer?

    public convenience init(configuration: Configuration = Configuration()) {
        self.init(configuration: configuration, source: SystemPasteboard(.general), now: Date.init)
    }

    init(configuration: Configuration, source: PasteboardSource, now: @escaping () -> Date) {
        self.configuration = configuration
        self.source = source
        self.now = now
        self.lastChangeCount = source.changeCount
    }

    deinit {
        timer?.cancel()
    }

    // MARK: - Public API

    /// Text copied within `maxAge` seconds, cleaned and redacted, or nil. Starts change-count monitoring on first
    /// use so later copies are timed accurately.
    public func recentText(maxAge: TimeInterval) -> String? {
        startMonitoring()
        let (count, copiedAt) = poll()
        guard let copiedAt, now().timeIntervalSince(copiedAt) <= maxAge else { return nil }

        if let cached = lock.withLock({ cached }), cached.changeCount == count {
            return cached.text
        }
        switch source.access {
        case .denied:
            return nil
        case .prompts where !configuration.readWhenItWouldPrompt:
            return nil
        default:
            break
        }
        let text = Self.process(types: source.types, string: self.source.string, configuration: configuration)
        lock.withLock {
            // Only cache if nothing new was copied while reading.
            if lastChangeCount == count { cached = (count, text) }
        }
        return text
    }

    /// Samples the change count and records when it moved. Cheap, and never reads the contents.
    @discardableResult
    public func poll() -> (changeCount: Int, changedAt: Date?) {
        let count = source.changeCount
        return lock.withLock {
            if count != lastChangeCount {
                lastChangeCount = count
                changedAt = now()
                cached = nil
            }
            return (lastChangeCount, changedAt)
        }
    }

    /// Samples the change count every `pollInterval` on a background queue, so a copy's age is known even when
    /// nobody asked for a while. Idempotent.
    public func startMonitoring() {
        lock.withLock {
            guard timer == nil, configuration.pollInterval > 0 else { return }
            let t = DispatchSource.makeTimerSource(queue: DispatchQueue.global(qos: .utility))
            t.schedule(deadline: .now() + configuration.pollInterval, repeating: configuration.pollInterval, leeway: .milliseconds(250))
            t.setEventHandler { [weak self] in self?.poll() }
            t.resume()
            timer = t
        }
    }

    public func stopMonitoring() {
        lock.withLock {
            timer?.cancel()
            timer = nil
        }
    }

    /// Current access state for the general pasteboard.
    public var access: Access { source.access }

    /// Reads the pasteboard once so the system shows its alert now (for onboarding, after the user turned clipboard
    /// context on), which also lists Tabber in System Settings where "Always Allow" can be chosen.
    /// Returns the access state afterwards.
    @discardableResult
    public func requestAccess() -> Access {
        _ = source.string
        return source.access
    }

    // MARK: - Rules

    /// Filters one pasteboard read. Nil for skipped types, empty text, secret-looking tokens, and text that is
    /// nothing but redactions.
    /// The types are checked first, so a skipped item's contents are never read.
    static func process(types: [String], string: @autoclosure () -> String?, configuration: Configuration) -> String? {
        if types.contains(where: configuration.skippedTypes.contains) { return nil }
        guard let raw = string() else { return nil }
        var text = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !text.isEmpty else { return nil }
        if SecretRedactor.looksLikeSecretToken(text) { return nil }
        if text.count > configuration.maxCharacters {
            text = String(text.prefix(configuration.maxCharacters))
        }
        if configuration.redactSecrets {
            text = SecretRedactor.redact(text)
            let remainder = text.replacingOccurrences(of: SecretRedactor.placeholder, with: " ")
            if TextSimilarity.words(remainder).isEmpty { return nil }
        }
        return text
    }
}

// MARK: - Pasteboard access

protocol PasteboardSource: AnyObject {
    var changeCount: Int { get }
    var types: [String] { get }
    var string: String? { get }
    var access: ClipboardContextProvider.Access { get }
}

final class SystemPasteboard: PasteboardSource {
    private let pasteboard: NSPasteboard

    init(_ pasteboard: NSPasteboard) {
        self.pasteboard = pasteboard
    }

    var changeCount: Int { pasteboard.changeCount }
    var types: [String] { pasteboard.types?.map(\.rawValue) ?? [] }
    var string: String? { pasteboard.string(forType: .string) }

    var access: ClipboardContextProvider.Access {
        if #available(macOS 15.4, *) {
            switch pasteboard.accessBehavior {
            case .alwaysAllow: return .allowed
            case .alwaysDeny: return .denied
            case .ask: return .prompts
            case .default:
                // Never asked yet. The alert is enforced from macOS 27; before that it was an opt-in preview.
                return ProcessInfo.processInfo.isOperatingSystemAtLeast(
                    OperatingSystemVersion(majorVersion: 27, minorVersion: 0, patchVersion: 0)
                ) ? .prompts : .allowed
            @unknown default:
                return .prompts
            }
        }
        return .allowed
    }
}
